class Solution {
public:
    int minProcessingTime(vector<int>& processorTime, vector<int>& tasks) {
        sort(processorTime.begin(), processorTime.end());
        sort(tasks.rbegin(), tasks.rend());
        int ans = 0;
        for (int i = 0; i < processorTime.size(); i++) {
            ans = max(ans, processorTime[i] + tasks[4 * i]);
        }
        return ans;
    }
};

class Solution {
    public int minProcessingTime(List<Integer> processorTime, List<Integer> tasks) {
        Collections.sort(processorTime);
        tasks.sort(Collections.reverseOrder());
        int ans = 0;
        for (int i = 0; i < processorTime.size(); i++) {
            ans = Math.max(ans, processorTime.get(i) + tasks.get(4 * i));
        }
        return ans;
    }
}

/**
 * @param {number[]} processorTime
 * @param {number[]} tasks
 * @return {number}
 */
var minProcessingTime = function(processorTime, tasks) {
    processorTime.sort((a, b) => a - b);
    tasks.sort((a, b) => b - a);
    let ans = 0;
    for (let i = 0; i < processorTime.length; i++) {
        const val = processorTime[i] + tasks[4 * i];
        if (val > ans) ans = val;
    }
    return ans;
};
